const std = @import("std");
const regex = @import("regex");
pub fn main(init: std.process.Init) !void {
    const a = std.heap.page_allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var args = try std.process.Args.Iterator.initAllocator(init.minimal.args, a);
    defer args.deinit();
    _ = args.next();
    const input = try std.Io.Dir.cwd().readFileAlloc(io, args.next().?, a, .limited(4 * 1024 * 1024));
    defer a.free(input);
    var re = try regex.Regex.compileWithFlags(a, "==(.+?)==", .{ .ecmascript = true });
    defer re.deinit();
    const matches = re.findAll(a, input) catch |err| {
        std.debug.print("{{\"error\":\"{s}\"}}\n", .{@errorName(err)});
        return err;
    };
    defer {
        for (matches) |*m| m.deinit(a);
        a.free(matches);
    }
    for (matches) |m| {
        const row = try std.json.Stringify.valueAlloc(a, .{ .start = m.start, .end = m.end, .text = m.slice, .captures = m.captures }, .{});
        defer a.free(row);
        std.debug.print("{s}\n", .{row});
    }
    std.debug.print("{{\"count\":{d}}}\n", .{matches.len});
}

