const fs = require('node:fs');
const cases = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
for (const c of cases) {
  const re = new RegExp(c.pattern, c.flags);
  const m = re.exec(c.input);
  const row = {id:c.id,error_name:null,index:null,end:null,text:null,captures:[]};
  if (m) {
    row.index = Buffer.byteLength(c.input.slice(0,m.index));
    row.end = Buffer.byteLength(c.input.slice(0,m.index+m[0].length));
    row.text=m[0]; row.captures=m.slice(1).map(x=>x===undefined?null:x);
  }
  console.log(JSON.stringify(row));
}

