const std = @import("std");
const Regex = @import("regex").Regex;
const Cache = @import("cache").Cache;
pub fn main(init: std.process.Init) !void {
    const a = std.heap.page_allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var args = try std.process.Args.Iterator.initAllocator(init.minimal.args, a);
    defer args.deinit();
    _ = args.next();
    const input = try std.Io.Dir.cwd().readFileAlloc(io, args.next().?, a, .limited(4 * 1024 * 1024));
    defer a.free(input);
    var cache = Cache.init(a);
    defer cache.deinit();
    const owned = try Cache.OwnedProgram.create(a);
    const compile_allocator = owned.compileAllocator();
    const compiled = try compile_allocator.create(Regex);
    compiled.* = try Regex.compileWithFlags(compile_allocator, "==(.+?)==", .{ .ecmascript = true });
    owned.publish(compiled);
    var lease = cache.adopt("==(.+?)==", "g", owned);
    defer lease.release();
    for (0..3) |iteration| {
        var pos: usize = 0;
        var count: usize = 0;
        while (pos <= input.len) {
            var found = (try lease.findFrom(input, pos)) orelse break;
            pos = found.value.end;
            count += 1;
            found.deinit();
        }
        std.debug.print("{{\"iteration\":{d},\"matches\":{d},\"compile_arena_bytes\":{d},\"matcher_arena_bytes\":{d},\"result_arena_bytes\":{d}}}\n", .{iteration,count,owned.compile_arena.queryCapacity(),owned.matcher_arena.queryCapacity(),owned.result_arena.queryCapacity()});
    }
}
